\label{lem:coalescence}
Let $\textrm{\upshape M}$ have rank $r\geqslant2$ on $E$, and let $\mathcal{H}$ be a
family of proper spanning subsets satisfying
\begin{enumerate}[(a)]
\item $\operatorname{rk}_{\textrm{\upshape M}}(H\cap H')\leqslant r-2$ for distinct
$H,H'\in\mathcal{H}$;
\item $\operatorname{cl}_{\textrm{\upshape M}}(I)\subseteq H$ whenever $I\subseteq H\in\mathcal{H}$
is independent and $|I|=r-1$.
\end{enumerate}
Then $\mathcal{H}$ uniquely determines a hyperplane coalescence $\textrm{\upshape M}'$ of $\textrm{\upshape M}$, which has bases 
\[
\mathcal{B}(\textrm{\upshape M}') = \{B \in \mathcal{B}(\textrm{\upshape M}) \colon B \notin H \in \mathcal{H}\}. 
\]
and rank function
\begin{equation}\label{eq:coalescence-rank}
\operatorname{rk}_{\textrm{\upshape M}'}(S)=
\begin{cases}
r-1,&\operatorname{rk}_{\textrm{\upshape M}}(S)=r\text{ and }S\subseteq H\text{ for some }H\in\mathcal{H},\\
\operatorname{rk}_{\textrm{\upshape M}}(S),&\text{otherwise.}
\end{cases}
\end{equation}

\label{prop:coalescence-zeta}\label{cor:coalescence-zeta}
For every $m \geqslant 0$, 
\begin{equation}\label{eq:coalescence-zeta}
Z_{\textrm{\upshape M}'}(m)=Z_{\textrm{\upshape M}}(m)-\sum_{H\in\mathcal{H}}
\left(Z_{\textrm{\upshape M}^{H}}(m)-\sum_{i=0}^{m}Z_{\mathrm{Tr}(\textrm{\upshape M}^H)}(i)\right).
\end{equation}

\label{lem:coalescence-flags}
For every $S\subseteq[r-2]$, 
\begin{equation}\label{eq:coalescence-flags}
\begin{aligned}
\alpha_{\textrm{\upshape M}'}(S)&=\alpha_{\textrm{\upshape M}}(S), \\
\alpha_{\textrm{\upshape M}'}(S\cup\{r-1\})&=\alpha_{\textrm{\upshape M}}(S\cup\{r-1\}) +\sum_{H\in\mathcal{H}}
\bigl(\alpha_{\textrm{\upshape M}^H}(S)-\alpha_{\textrm{\upshape M}^H}(S\cup\{r-1\})\bigr).
\end{aligned}
\end{equation}

\label{lem:coalescence-chow}\label{prop:coalescence-chow}\label{prop:local-polynomials}
For $P=f$ or $P=\underline{\textrm{\upshape H}}$,
\begin{equation}\label{eq:coalescence-chow}
P(\textrm{\upshape M}';t)=P(\textrm{\upshape M};t)-\sum_{H\in\mathcal{H}}
\bigl(P(\textrm{\upshape M}^H;t)-(1+t)P(\mathrm{Tr}(\textrm{\upshape M}^H);t)\bigr).
\end{equation}

Let $V=\mathbb{F}_q^4$ and let $\mathcal{S}$ be a spread of $\textrm{\upshape PG}(3,q)$. Let two distinct affine subspaces $P = a+ D, P' = b +D'$ of $V$ be given by distinct directions $\mathbb{P}(D) \ne \mathbb{P}(D')$ in $\mathcal{S}$. Since elements in $\mathcal{S}$ do not share common points, Lemma~\ref{lem:affine-intersections} implies that two distinct affine planes $P, P'$ in $\mathcal{A}(\mathcal{S})$
are either parallel and disjoint, or meet in exactly
one point. See Figure~\ref{fig:affine-spaces-giving-spreads}. 

